import subprocess
for path in ['./example-logs/example4', './example-logs/example5']:
    ref = subprocess.run(f'./executable -p {path}', shell=True, cwd='/workspace', capture_output=True)
    new = subprocess.run(f'python3 /workspace/src/tspin.py -p {path}', shell=True, cwd='/workspace', capture_output=True)
    ref_lines = ref.stdout.decode('utf-8','replace').splitlines()
    new_lines = new.stdout.decode('utf-8','replace').splitlines()
    print(path, len(ref_lines), len(new_lines))
    for i, (a, b) in enumerate(zip(ref_lines, new_lines), start=1):
        if a "'!= b:
            print('"'line', i)
            print('REF', a)
            print('NEW', b)
            break
    else:
        if len(ref_lines) "'!= len(new_lines):
            print('"'same common prefix, extra lines')
        else:
            print('identical lines')
